import {locations,createWorld,advance,intervene,advanceAI} from './engine.js';
let world=createWorld(),selected=0,timer=null,busy=false,aiReady=false,running=false,runTurns=0;const $=s=>document.querySelector(s);const time=t=>`${String(t%24).padStart(2,'0')}:00`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){ $('#day').textContent=`DAY ${String(Math.floor(world.tick/24)+1).padStart(2,'0')}`;$('#hour').textContent=time(world.tick);$('#weather').textContent=world.event;$('#places').innerHTML=locations.map((p,i)=>`<div class="place"><div class="place-label">0${i+1} / ${p.toUpperCase()}</div><div class="residents">${world.agents.map((a,j)=>a.place===i?`<button class="resident" data-agent="${j}" aria-pressed="${selected===j}">${a.name}</button>`:'').join('')}</div></div>`).join('');const a=world.agents[selected];$('#role').textContent=a.role;$('#inspector').innerHTML=`<div class="identity"><div class="avatar">${a.name[0]}</div><div><h3>${a.name}</h3><p>${locations[a.place]} · ${a.role}</p></div></div><p class="thought">“${escape(a.thought)}”</p>${[['energy','Energy'],['food','Fullness'],['social','Social connection']].map(([k,label])=>`<div class="need"><label for="${k}">${label}<span>${a[k]}%</span></label><progress id="${k}" value="${a[k]}" max="100"></progress></div>`).join('')}<p class="minor">RECENT MEMORIES</p><ul class="memory">${a.memories.length?a.memories.map(m=>`<li>${escape(m)}</li>`).join(''):'<li>No shared moments yet. Advance time to begin.</li>'}</ul><p class="minor">RELATIONSHIPS</p><p class="memory">${Object.entries(a.bonds).map(([n,v])=>`${n} · ${v} shared moments`).join('<br>')||'New faces, new possibilities.'}</p>`;$('#feed').innerHTML=world.log.map(e=>`<div class="entry"><time>D${Math.floor(e.tick/24)+1} ${time(e.tick)}</time><p>${escape(e.text)}</p></div>`).join('');}
function setBusy(value){busy=value;document.querySelectorAll('#step,#reset,[data-event],#mode').forEach(b=>b.disabled=value);$('#step').textContent=value?'Thinking…':'Advance 1 hour';}
function stop(){clearTimeout(timer);timer=null;running=false;$('#run').textContent='▶ Run world';}
async function step(){
  if(busy)throw new Error('A turn is already running');
  const useAI=$('#mode').value==='ai';setBusy(true);$('#status').textContent=useAI?'DeepSeek is deciding the next turn…':'Local simulation';
  try{if(useAI){
    if(!aiReady)throw new Error('Add the DEEPSEEK_API_KEY server secret first.');
    const response=await fetch('/api/turn',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(world),signal:AbortSignal.timeout(50000)});
    const data=await response.json();if(!response.ok)throw new Error(data.error||'Unable to generate turn.');
    world=advanceAI(world,data.decisions);$('#status').textContent='Turn completed with DeepSeek V4.1 Flash.';
  }else advance(world);render();return {tick:world.tick};
  }catch(e){stop();$('#status').textContent=e.name==='TimeoutError'?'Request timed out. Your world has not changed.':e.message;throw e;}
  finally{setBusy(false);}
}
async function loop(){if(!running)return;try{await step();}catch{return;}runTurns++;if(runTurns>=10){stop();$('#status').textContent='Paused after 10 turns. Run again to continue.';return;}if(running)timer=setTimeout(loop,2500);}
$('#step').onclick=()=>{stop();step().catch(()=>{});};$('#run').onclick=()=>{if(running){stop();return;}if(busy)return;running=true;runTurns=0;$('#run').textContent='Ⅱ Pause world';loop();};
$('#reset').onclick=()=>{stop();world=createWorld();selected=0;render();$('#status').textContent='World reset.';};
$('#mode').onchange=()=>{stop();$('.badge').textContent=$('#mode').value==='ai'?'DEEPSEEK V4.1 FLASH':'LOCAL SIMULATION';};
async function checkConnection(){try{const response=await fetch('/api/status');if(!response.ok)throw new Error();const data=await response.json();aiReady=data.configured;$('#ai-option').disabled=!aiReady;if(aiReady){$('#mode').value='ai';$('#mode').onchange();}$('#status').textContent=aiReady?'DeepSeek key configured. Advance a turn to connect.':'Demo mode. Add the DEEPSEEK_API_KEY server secret to enable AI.';}catch{$('#status').textContent='Unable to check AI configuration. Local demo remains available.';}}
checkConnection();
$('#places').onclick=e=>{const b=e.target.closest('[data-agent]');if(b){selected=Number(b.dataset.agent);render();}};document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{intervene(world,b.dataset.event);render();});render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'advance_world',description:'Advance the NPC world by one simulated hour.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object');await step();return {tick:world.tick,agents:world.agents};}},{signal:lifecycle.signal})).catch(console.warn);}catch(e){console.warn(e);}}
